    method PushFast(element: A)
      requires Valid?()
      requires size < capacity
      reads this, Repr
      modifies Repr
      ensures Valid?()
      ensures fresh(Repr - old(Repr))
      ensures size == old(size) + 1
      ensures capacity == old(capacity)
