                  + s[2] as uint64 * 0x100_0000_0000
                  + s[3] as uint64 * 0x1_0000_0000
                  + s[4] as uint64 * 0x100_0000
                  + s[5] as uint64 * 0x1_0000
                  + s[6] as uint64 * 0x100
                  + s[7] as uint64);
    ==
