    var x4 := x3 - (b4 as uint64 * 0x100_0000);

    var b5 := (x4 / 0x1_0000) as uint8;
    var x5 := x4 - (b5 as uint64 * 0x1_0000);

    var b6 := (x5 / 0x100) as uint8;
    var b7 := (x5 % 0x100) as uint8;
